import json, re, html, hashlib
from pathlib import Path

ROOT=Path('/workspace/scratch/f85ae98f1669')
SITE=ROOT/'tmp/batch-engineering/current-site'
LIVE=SITE/'library/data/tzidkat-hatzadik'
BOOKS=SITE/'mcp-data/text'
CACHE=json.loads((ROOT/'review-work/ois91-primary.json').read_text())
CATALOG=json.loads((SITE/'mcp-data/catalog.json').read_text())['books']
CONNECTED=json.loads((SITE/'library/connected-ideas/catalog.json').read_text())['records']
E=[]
def clean(t):return re.sub(r'\s+',' ',html.unescape(re.sub('<[^>]*>','',t))).strip()
def plain(t):return html.unescape(re.sub('<[^>]*>','',t))
def he(ref,*indices):
    t=CACHE[ref]['he']
    for i in indices:t=t[i-1]
    return re.sub('[\u0591-\u05c7]','',clean(t))
def span(ref,a,b):return ' '.join(he(ref,i) for i in range(a,b+1))
def sub(t,start=None,end=None):
    if start:t=t[t.index(start):]
    if end:t=t[:t.index(end)]
    return t.strip()
def row(book,ref):return next(x for x in json.loads((BOOKS/f'{book}.json').read_text())['paras'] if x['r']==ref)
def local(book,ref,lo=0,hi=None):
    r=row(book,ref)
    return clean(' '.join(x[0] for x in r['p'][lo:hi]) if 'p'in r else r['t'])
def pg(n,i):return {'neimosA':n,'integratedA':i}
P={91:pg(list(range(249,254)),list(range(285,290))),92:pg(list(range(253,256)),list(range(289,292))),93:pg(list(range(256,260)),list(range(292,296))),94:pg([259,260],[295,296]),95:pg(list(range(260,264)),list(range(296,299)))}
def add(s,id,pi,ref,h,en,context,anchorEnd=None,url=None,book=None,cacheRef=None,indices=None,webRef=None):
    r=next(x for x in json.loads((LIVE/f'{s-1}.json').read_text()) if x['n']==1)
    full=plain(r['p'][pi][0])
    anchor=full if anchorEnd is None else full[:full.index(anchorEnd)+len(anchorEnd)]
    if book:
        canonical=row(book,ref)
        b=next(x for x in CATALOG if x['slug']==book)
        sectionRef=b['sections'][canonical['s']]['ref']
        url='#/read/'+sectionRef.replace(' ','_')
        assert h in local(book,ref),(ref,'noncontiguous canonical quotation')
    else:url=url or 'https://www.sefaria.org/'+ref.replace(' ','_')
    ev={'ref':ref,'url':url,'he':h,'en':en,'translation':'Original English translation prepared directly from the cited Hebrew or Aramaic.','coverage':'Complete selected source unit; qualifications needed for its meaning retained.','heSha256':hashlib.sha256(h.encode()).hexdigest()}
    if book:ev.update(canonicalReaderRef=ref,canonicalSourceFile=f'mcp-data/text/{book}.json',contextHe=local(book,ref))
    if cacheRef:ev.update(cacheRef=cacheRef,retrievalURL=CACHE[cacheRef]['retrievalURL'],heVersionTitle=CACHE[cacheRef].get('heVersionTitle'))
    if indices is not None:ev['sourceIndex']=indices
    if webRef:ev['webRef']=webRef
    e={'section':s,'id':id,'rowN':1,'phraseIndex':pi,'heAnchorPrefix':anchor,'heCharOffset':len(anchor),'ref':ref,'url':url,'he':h,'en':en,'context':context,'sourceEvidence':[ev],'reviewEvidence':{'pdfPages':P[s],'preserveExisting':True,'status':'verified','dedup':'Compared all native and connected notes in this destination ois. The selected passage is not already quoted there.','method':'Both supplied editions reviewed; original source checked in context; exact current Hebrew anchor verified.'}}
    if book:
        e['readerRef']=ref
        e['reviewEvidence']['readerHebrewAlignment']={'canonicalRef':ref,'canonicalHebrewSha256':ev['heSha256'],'existingSourceTextUnchanged':True}
    else:e['openExternal']=True
    E.append(e)

# Ois 91: the source of possessions, the deed's consequences, and Jacob's flocks.
add(91,'tzidkat-possessions-and-the-root-of-life',0,'Tzidkat HaTzadik 86:1',local('tzidkat-hatzadik','Tzidkat HaTzadik 86:1',0,9),
    'Everything belonging to a person—his wife and children, his male and female servants, his ox and donkey, his tent, his silver and gold, and all that he has—comes from the root of his soul. For all inanimate things, plants, and animals are also rooted in the human soul, and the root of their life comes from it, as is known. What is acquired by him is that whose life is rooted in him. Ownerless possessions and all the beasts of the forest exist because he has not yet repaired the entire root of his life, for these certainly also relate to a person. Concerning the future it is said, “The wolf shall dwell with the lamb.” Likewise, before the sin the serpent served the human being. As the person is, so are his possessions, as it is stated concerning Rabbi Pinchas ben Yair’s donkey: the Holy One, blessed be He, does not bring a stumbling block through the animals of the righteous. Likewise, all the species in Noach’s ark, which he fed, presumably came from his root, as explained above. Therefore the Sages said that they had not corrupted their ways.',
    'The earlier ois states the principle developed here and includes the case of creatures that are not presently someone’s property. Their present condition is distinguished from their future repair.',book='tzidkat-hatzadik')
add(91,'vayikra-rabbah-for-the-sake-of-israel',1,'Vayikra Rabbah 36:4',sub(he('Vayikra Rabbah 36:4'),'אמר רבי ברכיה שמים','אמר רבי אחא'),
    'Rabbi Berekhiah said: Heaven and earth were created only for Israel’s merit, as it is written, “In the beginning God created.” “Beginning” refers to Israel, as it is stated, “Israel is holy to Hashem, the first of His produce.”',
    'This is the Midrashic derivation behind “for the sake of Israel.” The quoted sentence is Rabbi Berekhiah’s teaching within a passage that also relates creation to Yaakov and Moshe.',cacheRef='Vayikra Rabbah 36:4')
add(91,'eliyahu-even-instruments-of-harm',11,'Tanna DeBei Eliyahu Rabbah 24:1',sub(he('Tanna DeBei Eliyahu Rabbah 24',1),'וזהו משל הדיוט','ולא זו בלבד'),
    'This is the common proverb that people use: even the stone over which people stumble, or with which they are stoned, and the peg used for those hanged on trees, are destined to give an accounting.',
    'The original passage extends accountability even to instruments through which harm occurs. Rav Tzadok explains that image here through the human deeds from which their harmful condition arises.',cacheRef='Tanna DeBei Eliyahu Rabbah 24',indices=[1])
add(91,'yisrael-kedoshim-the-deed-itself-pursues',12,'Yisrael Kedoshim 5:34',local('yisrael-kedoshim','Yisrael Kedoshim 5:34',34,35),
    'This is the meaning of “Evil pursues [sinners]”: the evil and the transgression themselves. For “the consequence of a transgression is a transgression,” and it itself is what punishes and exacts retribution.',
    'This is Rav Tzadok’s explicit interpretation of the verse quoted here: the consequence proceeds from the wrong itself. The selection is the complete statement of that principle, without detaching an accusation from the surrounding discussion of Rabbi’s mules.',book='yisrael-kedoshim',anchorEnd='"חַטָּאִים תְּרַדֵּף רָעָה"')
add(91,'zikhronot-returning-creation-to-its-source',22,'Sefer HaZikhronot 4:14',local('sefer-hazikhronot','Sefer HaZikhronot 4:14'),
    'The commandment “Hear, Israel,” and so forth, concerns unity through hearing and faith. Once you have acknowledged His kingship over everything, no more is required: contemplation is not necessary, but rather accepting the yoke of Heaven’s kingship through faith, knowing that nothing is separate from Him or interposes before Him even after the world was created. But the commandment “You shall know,” and so forth, concerns contemplating this. This is the entire wisdom of the Work of Creation and the Work of the Chariot known to the masters of truth. The whole purpose of this wisdom is to demonstrate the truth of this unity: all creation, which appears separate from the Creator, has in truth no separation at all. This is the purpose of all creation—that all created beings recognize that they are not something separate from the Creator. This is the entire purpose of Torah and all the commandments: to purify the heart until it reaches this knowledge and apprehension through seeing and contemplation—that in every human activity, deed, and device, in everything whatsoever, nothing is separate from Him, blessed be He.',
    'The parallel explains the act of returning to the source as recognition and contemplation of dependence on the Creator. It distinguishes accepting this in faith from attaining it through contemplation.',book='sefer-hazikhronot')
add(91,'kometz-jacobs-flocks-and-the-souls',25,'Kometz HaMinchah 2:77:1',local('kometz-haminchah','Kometz HaMinchah 2:77:1',19,32),
    'Yaakov encompasses the six hundred thousand souls of Israel. Therefore the Sages said in Bereshit Rabbah that he had six hundred thousand flocks of sheep: his property came from the portions of life. He rescued these from Lavan, for they were also rooted in him, since they issued from his daughters; but Yaakov rescued and separated the portion of life from him. After the birth of the tribes, which completed the form of the six hundred thousand souls, he saw the need “to provide for his own household,” to bring in property—that is, to repair all the particular portions of his soul.',
    'This supplies Rav Tzadok’s own fuller explanation of the correspondence between Yaakov’s flocks and the souls included within him. The acquisition is described as a work of separation and repair.',book='kometz-haminchah')
add(91,'bava-metzia-the-house-of-jacob',27,'Bava Metzia 33b:2-3',span('Bava Metzia 33b',2,3),
    'What did they expound? As Rabbi Yehudah son of Rabbi Ilai expounded: What is the meaning of “Tell My people their transgression, and the house of Yaakov their sins”? “Tell My people their transgression”—these are Torah scholars, whose inadvertent offenses are treated for them as deliberate ones. “And the house of Yaakov their sins”—these are the unlearned, whose deliberate offenses are treated for them as inadvertent ones. This is what we learned: Rabbi Yehudah says, “Be careful in study, for an error in study is counted as a deliberate offense.”',
    'This is the precise teaching behind the reference to the end of Elu Metziot. It uses “the house of Yaakov” for the unlearned and contrasts their responsibility with the greater responsibility of scholars.',cacheRef='Bava Metzia 33b',indices=[2,3])
add(91,'peri-shavuot-jacob-and-his-descendants',28,'Peri Tzadik, Shavuot 10:2',sub(local('peri-tzadik','Peri Tzadik, Shavuot 10:2'),'וזה שא\' אחר כך ברע"מ'),
    'This is what is then stated in Raaya Mehemna: the barley omer is animal food, and so forth, and of them it is said, “You are My flock, the flock of My pasture; you are human.” We find concerning Yaakov our father that he had six hundred thousand flocks of sheep, as the Midrash says: Reish Lakish says six hundred thousand; the Rabbis say one million two hundred thousand; they do not disagree, and so forth. The number six hundred thousand signifies the holiness of the congregation of Israel, which is six hundred thousand. Until the giving of the Torah, Israel were in the category of sheep—“the flock of My pasture.” They attained the holiness of the category of humanity—“you are called human”—only after the giving of the Torah, when they attained the beauty of Adam before the corruption. Although Yaakov himself truly possessed the very beauty of Adam, as stated in the holy Zohar, this concerned him personally: he was like Adam before the sin. But for his descendants he did not attain the level of “you are human” until after the giving of the Torah; before the giving of the Torah they were in the category of sheep. Although Yaakov our father said of himself, “The God who shepherds me,” considering himself also to be in the category of sheep—as the Midrash says, “There is no occupation more lowly than a shepherd,” and so forth—David said, “From the elders I gain understanding”: Yaakov called Him a shepherd, and so forth. The reason is that Yaakov considered himself to be in the category of sheep. In particular, the flocks that allude to his descendants really were in the category of sheep until the giving of the Torah, when they attained the level of “you are human.” For this reason we offer barley, animal food, in the omer. On Shavuot, the time when our Torah was given, when they had already merited being called human, with Adam’s beauty, the offering is “Eat of My bread”—the two loaves.',
    'This parallel preserves an important distinction: Yaakov’s own attainment is not equated with that of his descendants before Sinai. It explains why the flocks can symbolize the collective stage before the giving of the Torah.',book='peri-tzadik')

# Ois 92: an opening is an invitation to repentance and still requires a response.
add(92,'tzidkat-the-higher-repentance-and-flood',2,'Tzidkat HaTzadik 132:1',local('tzidkat-hatzadik','Tzidkat HaTzadik 132:1',10,17),
    'In the heart there is a root of evil, as it is written, “For the inclination of the human heart is evil from youth”—that is, from its root; this concerns the sin of the generation of the Flood. Therefore repentance does not help for this, for it does not help a root of evil: evil does not become good. This refers to lower repentance. Rather, higher repentance is needed, from the World to Come, awakening from wisdom, which is the root of the root. There is no evil at all there in Israel, as it is said, “The soul You placed within me is pure.” For even the evil root has a root that is “very good,” as is known. [Therefore the Sages said that He gave the generation of the Flood a foretaste of the World to Come: this was to repair them as explained above, but it did not succeed.]',
    'The qualification is essential: Rav Tzadok limits the statement that repentance does not help to lower repentance, then describes the higher repentance that reaches the root’s own good source. He also states that the offered taste did not accomplish this repair in the Flood generation.',book='tzidkat-hatzadik')
add(92,'sanhedrin-the-short-extension-after-the-long',3,'Sanhedrin 108b:5',sub(he('Sanhedrin 108b',5),'דבר אחר: שקבע להם','דבר אחר: לשבעת'),
    'Another explanation: the Holy One, blessed be He, fixed a long period for them and afterward a short period.',
    'This supplies the third interpretation used in the ois. It concerns the seven days mentioned immediately before the Flood; Rav Tzadok connects that final short extension with an opening for repentance.',cacheRef='Sanhedrin 108b',indices=[5],anchorEnd='"זְמַן קָטָן אַחַר זְמַן גָּדוֹל"')
add(92,'yoma-ravia-and-the-scapegoat-comparison',4,'Yoma 42a:1-3',span('Yoma 42a',1,3),
    'For the red heifer [the scarlet wool weighs] ten zuz; for the scapegoat, two sela; and for the person with tzaraat, one shekel. Rabbi Yochanan said: Rabbi Shimon ben Chalafta and the Rabbis disagree concerning the red heifer: one says a weight of ten, and one says a weight of one shekel. Your mnemonic is “One who brings much and one who brings little.” Rabbi Yirmeyah of Difti said to Ravina: They do not disagree concerning the red heifer; they disagree concerning the scapegoat. On that day Ravia bar Kisi died, and they established this mnemonic: “Ravia [bar] Kisi atones like the scapegoat.”',
    'The specific comparison with the scapegoat occurs on Yoma 42a, in this memorial mnemonic. This supplies the original wording alongside the existing note’s other parallels concerning the death of the righteous.',cacheRef='Yoma 42a',indices=[1,2,3])
add(92,'poked-the-gift-and-the-required-human-response',6,'Poked Akarim 3:1',local('poked-akarim','Poked Akarim 3:1',9,27),
    'It is known what the Sages said concerning “Hashem is your shadow”: He is like the shadow that does what the body itself does. All His attributes are measure for measure; it is not without cause, but because they also turn their attention to Him. Yet the blessed God desires that awakening from below come first: “Return to Me and I shall return to you,” while we ask, “Bring us back to You, and we shall return.” For we have no strength to begin: You must first bring us back through awakening from above, and then we shall return. So it was in Egypt: through awakening from above, the blessed God sent them “I have surely taken notice,” and through this “they will listen to your voice”—they would immediately believe this declaration. By Moshe our teacher’s saying “I have surely taken notice,” he introduced into their hearts complete faith in the blessed God’s providence over them. They therefore listened specifically to his voice: through his voice he brought hearing into them, through that very voice and declaration of “I have surely taken notice,” which he placed within their hearts. As soon as this entered their hearts, they understood the truth that the blessed God was certainly taking notice of them. Once it was revealed in the depths of their hearts that He watches over them, and they believed this with complete faith, it was certainly fitting in judgment that He watch over them. The removal of providence and of God’s remembrance of a person occurs only when the person is also in concealment from God. But when a person remembers God and believes that God is with him and watches over all his affairs, God certainly remembers and watches over him too. In Egypt they had been utterly submerged in forgetfulness. They possessed this sign: the redeemer who spoke in the language of taking notice would introduce into their hearts the awareness and remembrance that there is a blessed Creator who directs, watches over, and can bring them out of Egypt. Through this, the corresponding attention above follows. There cannot be attention above without remembrance also entering their hearts. Sometimes the awakening above comes first, but afterward, in any event, there must be awakening below. This is the sign of the redeemer’s using the language of taking notice: they could immediately sense in their hearts whether that awareness arose within them too. So it was: “The people believed, and they heard that He had taken notice.” Through hearing that He had taken notice, faith entered their hearts.',
    'The complete unit distinguishes the initiative from above from the response that must follow below. It explains why receiving an opening does not dispense with the person’s own return.',book='poked-akarim')
add(92,'zohar-the-usual-order-of-awakening',7,'Zohar, Lech Lecha 4:18-20',span('Zohar, Lech Lecha 4:18-20',1,3),
    'When they departed, what is written? “To go to the land of Canaan”—their desire was to go there. From this we learn that whoever awakens to become pure is assisted. Come and see that this is so: once it says “to go to the land of Canaan,” immediately “Hashem said to Avram: Go forth.” Before he first awakened, “Go forth” was not written. Come and see: what is above does not awaken until an awakening below first provides something upon which the awakening above can rest. The mystery of the matter is that the dark light does not unite with the white light until it first awakens. Once it first awakens, the white light immediately rests upon it. Therefore it is written, “God, do not be silent; do not be still and do not be quiet, God,” so that the white light never cease from the world. Likewise, “You who mention Hashem, give yourselves no rest,” in order to awaken below that upon which awakening above may rest. Thus, once a person first awakens, the awakening above then arises. Come and see: once it is written, “They went forth with them from Ur Kasdim,” immediately, “Hashem said to Avram,” and so forth.',
    'This is the Zohar’s account of the ordinary sequence: human initiative followed by help from above. The ois contrasts that sequence with the exceptional prior opening given during the final days before the Flood.',cacheRef='Zohar, Lech Lecha 4:18-20',indices=[1,2,3])

# Ois 93: receiving an opening, the Second Temple, and Torah amid concealment.
add(93,'eikhah-the-plea-that-god-bring-us-back',1,'Eikhah Rabbah 5:21',sub(he('Eikhah Rabbah 5:21'),end='חדש ימינו כקדם'),
    '“Bring us back to You, Hashem, and we shall return.” The congregation of Israel said before the Holy One, blessed be He: Master of the world, it is Yours to bring us back. He said to them: It is yours, as it is stated, “Return to Me, and I shall return to you, says Hashem.” They said before Him: Master of the world, it is Yours, as it is stated, “Bring us back, God of our salvation.” Therefore it is said: “Bring us back to You, Hashem, and we shall return.”',
    'The Midrash presents the petition as a dialogue about who must begin the return. This is the background to Rav Tzadok’s reference to the plea “Bring us back.”',cacheRef='Eikhah Rabbah 5:21',anchorEnd='"הֲשִׁיבֵנוּ וְכוּלֵי"')
add(93,'bahya-the-presence-in-the-second-temple',4,'Rabbeinu Bahya, Bereshit 46:27:2',sub(he('Rabbeinu Bahya, Bereshit 46:27',2),'ומיום ששרתה שכינה'),
    'From the day the Divine Presence rested upon Mount Sinai at the giving of the Torah, it did not depart from Israel until the First Temple was destroyed. From the destruction of the First Temple, the Divine Presence did not rest among Israel, for in the Second Temple the Divine Presence did not rest. The intention is not to say that the Divine Presence did not rest in the Second Temple at all, for we find that it rests among twenty thousand, from what is written, “Return, Hashem, to the myriads of the thousands of Israel,” and, “The chariots of God are myriads, thousands upon thousands; Hashem is among them.” It need hardly be said that the Divine Presence rests among forty thousand. Moreover, Scripture testifies, “I shall be pleased with it and be glorified”—meaning: I shall cause the Glory, which is the Divine Presence, to rest in it. Rather, it did not rest there constantly as in the First Temple, because there were not six hundred thousand there: only forty thousand came up from Babylonia, as it is written, “The entire congregation together was forty thousand.” This is what the Sages expounded concerning “I shall be pleased with it and be glorified”: the written form of “be glorified” lacks the letter heh because five things were missing there—the Ark, the anointing oil, fire, the Divine Presence, and the Urim and Tummim. For this reason it says “be glorified,” to explain that the Glory, which is the Divine Presence, was there, but not Tiferet; this is the force of “be glorified,” excluding Tiferet. The missing heh, the last letter of the Name, indicates the absence of the Divine Presence, for it is among the five things that were missing. How was it absent, when Scripture says “I shall be glorified”? Rather, it did not rest there constantly as in the First Temple, but hovered over it. In the future, however, Israel will be numerous beyond counting. This is what is written: “The number of the children of Israel shall be like the sand of the sea.” It does not say, “The seed of Israel shall be like the sand of the sea,” but “the number”—meaning that those counted from twenty years of age and upward will be like the sand of the sea. Then Tiferet and the Glory will return. So Yeshayahu promised: “Arise, shine, for your light has come, and the glory of Hashem has shone upon you.” Understand this.',
    'Rabbeinu Bahya expressly qualifies the statement that the Divine Presence did not rest in the Second Temple: he distinguishes its constant dwelling from its intermittent or hovering presence. The whole qualification is retained, together with his distinction between Glory and Tiferet.',cacheRef='Rabbeinu Bahya, Bereshit 46:27',indices=[2])
add(93,'heikhalot-the-qualities-of-torah',5,'Pirkei Heikhalot Rabbati 28',
    'אמר ר\' ישמעאל כך אמר ר\' עקיבא משום ר\' אליעזר הגדול מיום שנתנה תורה עד שנבנה הבית האחרון תורה נתנה הדרה יקרה גדולתה וכבודה ותפארתה אימתה פחדה ויראתה עשרה גאותה וגאונה עוזה ועזוזה וכבודה לא נתנו עד שנבנה בית אחרון לא שרתה בה שכינה:',
    'Rabbi Yishmael said: Thus said Rabbi Akiva in the name of Rabbi Eliezer the Great: From the day the Torah was given until the last Temple was built, the Torah was given, but its splendor, preciousness, greatness, honor, beauty, awe, dread, fear, wealth, majesty, exaltation, strength, might, and honor were not given until the last Temple was built; the Divine Presence did not rest in it.',
    'This is the original Heikhalot passage behind the contrast between the giving of the Torah and the disclosure of its qualities during the Second Temple. The linked textual witness has a different enumeration from the seventeen mentioned in the ois, including a repeated “honor”; the author’s count is left unchanged.',url='https://mobile.tora.ws/html/15061-27.html',webRef='turn90view0')
add(93,'heikhalot-the-stones-and-the-revealed-secret',6,'Pirkei Heikhalot Rabbati 31:5',
    'אמר ר\' ישמעאל כך אמר ר\' עקיבא משום ר\' אליעזר הגדול לא קבלו עליהם אבותינו לשום אבן על אבן בהיכל עד שכפו למלכו של עולם וכל משרתיו ונזקקו להם וגילה להם סודה של תורה היאך יעשוהו והיאך ישתמשו בו מיד הופיע רוח הקדש ממבוי הגדול אשר בבית ה\' שלא ירדה ולא שרתה שכינה בבית קדשי הקדשים מפני הגזרה',
    'Rabbi Yishmael said: Thus said Rabbi Akiva in the name of Rabbi Eliezer the Great: Our ancestors did not undertake to place one stone upon another in the Sanctuary until they compelled the King of the world and all His servants, who attended to them, and He revealed to them the secret of Torah—how they should perform it and how they should make use of it. Immediately the holy spirit appeared from the great passageway in the House of Hashem, for the Divine Presence had neither descended nor rested in the Holy of Holies because of the decree.',
    'This supplies the actual passage about placing the stones and receiving Torah’s secret. It also retains the source’s qualification that the Divine Presence had not rested in the Holy of Holies because of the decree.',url='https://mobile.tora.ws/html/15061-30.html',webRef='turn90view1')
add(93,'yoma-the-surrender-of-the-idolatrous-inclination',8,'Yoma 69b:6-10',span('Yoma 69b',6,10),
    '“They cried out to Hashem God with a great voice.” What did they say? Rav said, and some say Rabbi Yochanan: Woe, woe! This is the one that destroyed the Temple, burned its Sanctuary, killed all the righteous, exiled Israel from their land, and still dances among us. Did You give it to us for any reason other than that we should receive reward through it? We want neither it nor its reward! A note fell to them from heaven, on which “Truth” was written. Rav Chanina said: Learn from this that the seal of the Holy One, blessed be He, is truth. They observed a fast for three days and three nights, and it was handed over to them. It emerged like a fiery lion cub from the Holy of Holies. A prophet said to Israel: This is the inclination to idolatry, as it is stated, “He said: This is wickedness.” As they seized it, a hair slipped from its mane; it cried out, and its voice traveled four hundred parasangs. They said: What shall we do? Perhaps, Heaven forbid, they will have mercy on it from heaven. A prophet told them: Throw it into a lead pot and cover its mouth with lead, for lead absorbs sound, as it is stated, “He said: This is wickedness. He cast it into the ephah and cast the lead weight over its mouth.”',
    'This is the account of the cancellation of the inclination to idolatry. The existing note quotes the subsequent attempt to cancel sexual desire; the present passage supplies the earlier, distinct event to which the ois also alludes.',cacheRef='Yoma 69b',indices=[6,7,8,9,10],anchorEnd='שֶׁאָמְרוּ בְּיוֹמָא (סט:)')
add(93,'berakhot-the-inclination-and-divine-help',8,'Berakhot 32a:2-4',span('Berakhot 32a',2,4),
    'Rabbi Chama son of Rabbi Chanina said: Were it not for these three verses, the feet of “the enemies of Israel” [a euphemism for Israel] would have collapsed. One is that it is written, “And whom I have caused harm”; another, “As clay in the potter’s hand, so are you in My hand, house of Israel”; and another, “I shall remove the heart of stone from your flesh and give you a heart of flesh.” Rav Pappa said: From here: “I shall place My spirit within you, and cause you to walk in My statutes.”',
    'This is the passage in the chapter Ein Omdin behind the reference to “whom I have caused harm.” The parallel in Sukkah 52b likewise cites these verses. The statement places human struggle alongside divine formation and help.',cacheRef='Berakhot 32a',indices=[2,3,4])
add(93,'derekh-hashem-persistent-study-and-its-limits',9,'Derekh Hashem, Part Four, On Torah Study 6',he('Derekh Hashem, Part Four, On Torah Study',6),
    'Torah study in relation to the influences it brings: The second condition is rectifying one’s conduct. One who wishes to draw down an influence must be worthy and prepared to draw it down. But if he defiles himself through guilt and transgression, distances himself from his Creator, and strays after the powers of impurity and evil, it will certainly be said of him: “To the wicked, God said: What right have you to recount My statutes?” Likewise the Sages said: Whoever teaches an unworthy student is as though he throws a stone to Markulis. Such a person’s Torah will certainly draw down none of the influence we have described. Nevertheless, the Sages revealed a great secret to us: had the wicked not abandoned Torah study, they would ultimately have returned to the good. Although they cannot draw down any influence from before Him, as explained, the words of Torah themselves remain holy in their own right. Through persistent engagement with them, they will bring the student, time after time, a little awakening, like the faintest glimmer of illumination, which will eventually prevail over him and bring him back to the good. This is what the Sages wrote: “If only they had abandoned Me but kept My Torah, for its light brings them back to the good.” It is clear, however, that this does not concern someone who engages with it as mockery or jest, or to give it interpretations contrary to halakhah. Rather, he must engage with it at least as someone engages with other fields of wisdom.',
    'Ramchal explains how continued study can gradually restore a person even when his conduct prevents the fuller influence of Torah. He explicitly excludes study undertaken as mockery or for distortion; that restriction is part of the quotation.',cacheRef='Derekh Hashem, Part Four, On Torah Study',indices=[6],anchorEnd='וְהָעֵצָה בְּהֶעְלֵם הוּא דִּבְרֵי תוֹרָה,')
add(93,'eikhah-the-light-of-torah-returns-them',9,'Eikhah Rabbah, Petichta 2',sub(he('Eikhah Rabbah, Petichta 2'),'רבי הונא ורבי ירמיה בשם רבי חיא בר אבא','רב הונא אמר'),
    'Rabbi Huna and Rabbi Yirmeyah said in the name of Rabbi Chiya bar Abba: It is written, “They abandoned Me and did not keep My Torah.” If only they had abandoned Me but kept My Torah! Through their engagement with it, the light within it would have brought them back to the good.',
    'This is the wording of the teaching at the opening of Eikhah Rabbah. It supplies the reason for the hope expressed in the ois: the Torah’s own light can bring its students back.',cacheRef='Eikhah Rabbah, Petichta 2')
add(93,'resisei-wisdom-and-prophecy-range-and-clarity',11,'Resisei Layla 52:7',local('resisei-layla','Resisei Layla 52:7',89,153),
    'Through the wisdom of the Oral Torah, which brings human wisdom into Torah, Esav and also Amalek are overcome, for through this one is attached to Torah’s hidden root. As it is written in Bava Batra: “A sage is greater than a prophet”; see Ramban there, who explains that this is attainment through the holy spirit. This means a spirit from the higher holiness—higher wisdom—which influences lower wisdom. The fiftieth gate hidden from Moshe our teacher refers to his attainment through prophecy, which is like seeing with his own eyes. Concerning this, according to one opinion in Rosh Hashanah, they said: “Among prophets none arose, but among kings one arose.” This means attainment through the attribute of kingship, lower wisdom. Although this is a lesser mode of attainment, it has an advantage in being able to attain matters that are higher. As is known, the divine Rabbi Yitzchak [the Ari] revealed the place and root from which Moshe our teacher’s attainment came, and he revealed lofty secrets far above that root. But all his attainments were only through the holy spirit, which bears no comparison with prophetic vision—even the unclear mirror of the other prophets, and all the more so the prophecy of Moshe our teacher. Prophetic attainment is revealed attainment, and through revelation one can attain only what can be attained in this world. Concerning the attainment of the World to Come, “No eye has seen”—meaning the eyes of the prophets, who see with the eye. The sages’ attainment, by contrast, comes from concealment, and they can also attain the hidden root. Although it is said concerning this, “Do not investigate what is beyond you,” and so forth—for the root hidden from every creature’s eye is called “beyond,” the supreme wonder, where there is no permission to inquire at all—this means attaining it completely through wisdom. Nevertheless, they have a hold upon it because the root of their wisdom comes from there. Since it is the wisdom of their hearts that has become Torah, it is attached to its root.',
    'The parallel distinguishes the range of wisdom’s subject matter from the clarity of prophetic vision. Its explicit qualification prevents the statement “a sage is greater” from being read as equating later inspiration with Moshe’s prophecy.',book='resisei-layla',anchorEnd='וְזֶה בֶּאֱמֶת גָּדוֹל יוֹתֵר')
add(93,'ramban-the-prophecy-of-wisdom',11,'Chiddushei Ramban on Bava Batra 12a:1',he('Chiddushei Ramban on Bava Batra 12a',1),
    'Regarding the statement, “From the day the Temple was destroyed, although prophecy was taken from the prophets, it was not taken from the sages”: Rashi explained, “Although it was taken from prophets who are not sages.” This can be challenged, for in tractate Nedarim we say that the Holy One, blessed be He, causes His Presence to rest only upon someone wise, strong, and wealthy. Some answered that He causes His Presence to rest without interruption only upon a sage, but a prophet sent on a mission is different, such as the prophecy of Yonah son of Amittai on the mission to Nineveh. I am not satisfied with this. Rather, it means: although the prophecy of the prophets, which is appearance and vision, was removed, the prophecy of the sages, which comes by way of wisdom, was not removed. They know the truth through the holy spirit within them. For on a temporary occasion He causes His Presence to rest even upon pious people who are not sages; there we say, “From where do we know this? From Moshe,” and Moshe’s prophecy did not cease. This is the force of the expression “causes His Presence to rest.” Although the proof concerning wealth is also brought from Yonah, he was a prophet without interruption, but was sent only to Nineveh.',
    'Ramban distinguishes prophetic appearance and vision from the sages’ knowledge of truth through the holy spirit. The quotation retains his objection to the alternative explanation and his distinction between continuous and occasional inspiration.',cacheRef='Chiddushei Ramban on Bava Batra 12a',indices=[1])

# Ois 94: the illumination that brings fear and its transformation into favor.
add(94,'rema-awareness-of-gods-presence-and-fear',0,'Rema, Shulchan Arukh, Orach Chayim 1:1',sub(he('Shulchan Arukh, Orach Chayim 1:1'),"שויתי ה' לנגדי תמיד",'ולא יתבייש'),
    '“I have placed Hashem before me always” is a great principle of Torah and of the virtues of the righteous who walk before God. A person’s sitting, movements, and activities when he is alone in his house are not like his sitting, movements, and activities when he is before a great king. Nor are his speech and free expression when he is with his household and relatives like his speech in the king’s presence. All the more so when a person takes to heart that the great King, the Holy One, blessed be He, whose glory fills the whole earth, stands over him and sees his deeds, as it is stated, “Can a man hide in hidden places and I not see him? says Hashem.” Immediately fear and submission will come upon him in awe of the blessed God, and shame before Him always. [Guide of the Perplexed, Part III, chapter 52.]',
    'Rema describes awareness of God’s presence as the immediate source of fear, submission, and shame. This gives the practical counterpart to the opening description of illumination leading to awe.',url='https://www.sefaria.org/Shulchan_Arukh%2C_Orach_Chayim.1.1',cacheRef='Shulchan Arukh, Orach Chayim 1:1',anchorEnd='וְעַל יְדֵי זֶה מַגִּיעַ לְיִרְאָה')
add(94,'pardes-faces-of-wrath-and-favor',1,'Pardes Rimmonim 23:17:13',sub(he('Pardes Rimonim 23:17',13),'ולפעמים יש פנים של זעם'),
    'Sometimes there is a face of wrath, as in “The face of Hashem dispersed them.” There is also a face of favor, as in “Shine Your face upon Your servant.” Everything depends upon the source from which it draws: when it draws from Chesed, there is a face of favor and mercy; when it draws from Gevurah, then, Heaven forbid, there is a face of wrath. In this way Rabbi Shimon bar Yochai explained in Raaya Mehemna, Ki Tetze, page 282a: the faces of the sun are Gedulah and Gevurah; the faces of the moon are Netzach and Hod. Those on the right are of mercy, and those on the left are of wrath. Everything depends upon the influence reaching the sun or the moon.',
    'The passage explains the same paired expressions within the symbolism of the sefirot. Favor and wrath describe differing influences, rather than two unrelated meanings of “face.”',cacheRef='Pardes Rimonim 23:17',indices=[13])
add(94,'bamidbar-the-removal-of-the-face-of-wrath',2,'Bamidbar Rabbah 11:7',sub(he('Bamidbar Rabbah 11:7'),end='דבר אחר'),
    '“May Hashem lift His face toward you,” and so forth: may He remove His anger from you. “Lift” here means removal, as in “Pharaoh will lift your head,” and so forth. “His face”—these are faces of wrath, as in “I shall set My face against that person,” and so forth. That is: He will remove from you those faces of wrath that were fit to come upon you.',
    'This is the Midrash’s opening interpretation of the priestly blessing. It explicitly reads the lifting of the face as the removal of the wrath that the person would otherwise encounter.',cacheRef='Bamidbar Rabbah 11:7')
add(94,'devarim-the-always-open-gates-of-repentance',5,'Devarim Rabbah 2:12',he('Devarim Rabbah 2:12'),
    'Another explanation of “like Hashem our God”: This is what Scripture says, “As for me, may my prayer to You, Hashem, be at a time of favor.” Rabbi Chanina bar Pappa asked Rabbi Shmuel bar Nachman: What is the meaning of this verse? He answered: The gates of prayer are sometimes open and sometimes locked, but the gates of repentance are always open. He asked: From where is this known? For it is written, “With awesome deeds in righteousness You answer us, God of our salvation, the trust of all the ends of the earth and of the distant sea.” Just as a ritual pool is sometimes open and sometimes locked, so the gates of prayer are sometimes open and sometimes locked; but as the sea is always open, so the hand of the Holy One, blessed be He, is always open to receive those who return. Rav Anan said: Even the gates of prayer are never locked, as it is written, “Like Hashem our God whenever we call to Him.” Calling means prayer, as it is stated, “Before they call, I shall answer.” Rabbi Chiya the Great said: It is written, “Hope to Hashem; be strong, and He will strengthen your heart; hope to Hashem.” Pray and pray again, for there is an hour when it will be granted to you. Another explanation of “As for me, may my prayer”: David said “a time of favor” because he was an individual. But the prayer of a congregation never returns empty. Thus: “Like Hashem our God whenever we call to Him.”',
    'The Midrash expressly states that the gates of repentance are always open. Its surrounding discussion also preserves the alternative opinion that the gates of prayer are never locked, and the distinction concerning communal prayer.',cacheRef='Devarim Rabbah 2:12',anchorEnd='פּוֹתֵחַ שַׁעַר לִתְשׁוּבָה,')
add(94,'bamidbar-rabbi-dosa-on-seeing-at-death',5,'Bamidbar Rabbah 14:22',sub(he('Bamidbar Rabbah 14:22'),'רבי דוסא אומר','רבי עקיבא אומר'),
    'Rabbi Dosa says: It is stated, “A human being cannot see Me and live.” During their lives they do not see, but at the time of their death they do see. Likewise it says, “Before Him all who go down to the dust shall bow, and he did not keep his soul alive.”',
    'Rabbi Dosa supplies the original teaching about seeing at the time of death. Rav Tzadok connects that encounter here with the continuing opening for repentance; that further connection is his explanation of the teaching.',cacheRef='Bamidbar Rabbah 14:22',anchorEnd='אָדָם רוֹאֶה שְׁכִינָה')
add(94,'berakhot-when-the-face-of-wrath-passes',7,'Berakhot 7a:5',he('Berakhot 7a',5),
    'Rabbi Yochanan also said in the name of Rabbi Yosei: From where do we know that one should not try to appease a person at the time of his anger? For it is written, “My face will go, and I shall give you rest.” The Holy One, blessed be He, said to Moshe: Wait for Me until the faces of wrath pass, and I shall give you rest.',
    'The Gemara reads the verse as the passing of wrath followed by rest. Rav Tzadok uses that reading at the conclusion of the ois to explain the transition beyond the unrest of fear.',cacheRef='Berakhot 7a',indices=[5])

# Ois 95: youthful desire, its holy use, and the qualified promise of repair.
add(95,'yisrael-kedoshim-the-root-and-its-future-repair',1,'Yisrael Kedoshim 10:4',local('yisrael-kedoshim','Yisrael Kedoshim 10:4'),
    'It is known that being called “evil” in the eyes of the blessed God concerns impairment of the covenant, as was said of Er: “Er, Yehudah’s firstborn, was evil in the eyes of Hashem, [and Hashem put him to death],” and of King David concerning that incident: “I have done what is evil in Your eyes.” This is the root of evil in creation: the creation of the foreskin that covers the holy covenant. It is named only after the nations, as it is said, “All the nations are uncircumcised,” as we learn in Nedarim; this is the root of the nations’ evil in creation. For this reason the commandment of circumcision was given to Israel, who can remove that evil present from birth, because for them it is not at the root, but like thorns surrounding the rose and thorns around a myrtle. Although evil also has a hold upon that limb in Israel—this is the touching of the hollow of Yaakov’s thigh, where Esav’s angel had the power to accuse, since there is some root there of the little folly present from birth, concerning which they said, “Full of iniquity—even the most pious of the pious intends only his own pleasure”—concerning this it is said, “I shall remove the heart of stone from your flesh and give you a heart of flesh.” The Sages expounded: “A heart to bring forth flesh.” This will occur only in the future, through the blessed God’s removal of the heart of stone by slaughtering the evil inclination. Although Yaakov our father merited this even in this world, as they said concerning “Give me my wife”—“It was said only to establish descendants”—and therefore it is stated that he did not die, nevertheless, on account of his descendants, who are not like this, the hollow of his thigh was touched. But all this is only temporary, in this world, which resembles night: it is the world of falsehood, which lasts “only for a moment.” As soon as the sun shone upon him, he was healed of his limp. For in truth even the uncircumcised of Israel are called circumcised, since the foreskin is not at their root at all, and “what is destined to be cut is regarded as already cut.”',
    'The parallel explains why an inclination present from youth is nevertheless open to repair. It preserves the difference between Yaakov’s individual attainment, his descendants’ present struggle, and the complete removal of the inclination in the future.',book='yisrael-kedoshim')
add(95,'dover-the-good-inclination-and-the-refinement-of-desire',2,'Dover Tzedek, Miscellany 4:40',local('dover-tzedek','Dover Tzedek, Miscellany 4:40',3,8),
    'Therefore the Zohar, Bereshit, page 52a, calls the good inclination “another serpent, of life.” For the inclination of the human heart means the desire within the heart, and every desire is called a serpent, because every desire may be for oneself and on one’s own account. Nevertheless, regarding Israel the Sages said in Rosh Hashanah that such a person is completely righteous even though he also intended his own benefit. It is therefore called “good” [the level of the righteous, as is known], and “of life” [for body and covenant are reckoned as one, and the body is called the tree of life]. Nevertheless, it is also called a serpent because it is not yet the choicest form. This is Yesod in a state of smallness, which is called a serpent, as the Ari wrote at the end of gate 21 of Peri Etz Chayim concerning the mystery of 160, because it draws from the rear aspect of the name Ehyeh; see there. The explanation is as stated in Pesachim: at first, when a person acts, he acts for himself. In a state of smallness a person does not yet have this additional understanding, to act without doing so for himself [from the root of the serpent’s incitement], for this still requires refinement. Yet this smallness too is attached to the blessed God’s very essence. It is the holy serpent that draws from the rear aspect of Ehyeh, for the Sages said concerning “You shall see My back”: this is the knot of the tefillin.',
    'Rav Tzadok explains that the same power of desire can operate as the good inclination even while mixed motives still require refinement. The positive designation does not erase the distinction between an initial stage and a more purified intention.',book='dover-tzedek',anchorEnd='מִצַּד הַיֵּצֶר הַטּוֹב')
add(95,'tzidkat-torah-desire-and-love-of-god',2,'Tzidkat HaTzadik 196:1',local('tzidkat-hatzadik','Tzidkat HaTzadik 196:1',4,17),
    'Love of Torah without the blessed God—that is, love of wisdom alone—is the generation of the Flood, concerning which the Zohar says that it was then fitting for the Torah to be given. For they loved Torah and wisdom greatly. This is the meaning of “the sons of God [came] to the daughters of man”: it is known that the feminine is desire and the masculine its fulfillment. Angels have wisdom and attainment, but they have no evil inclination or longing. As stated in Midrash HaNeʿelam, even desire for words of Torah requires the evil inclination. A human being has desire but lacks attainment, and then they joined—this is not the place to explain it. But without the blessed God, sexual wrongdoing proceeds from this. The children of Israel, the seed of Avraham who loved Me, have love of the blessed God fixed within them from birth and from the womb. This is the root, corresponding to Keter, which is beyond human grasp. Chokhmah and Binah are love of Torah and of Israel, for Binah is the heart, and there lies the chief love of companions, as it is written, “So the human heart to another.” Every attribute is a complete structure; these are the first three within the attribute of Chesed, and afterward the lower seven are their extension into the powers. They are the powers of nefesh, ruach, and neshamah: the bond of Israel to one another is from nefesh; the bond to Torah is from ruach; and the bond to the blessed God is from neshamah, which is beneath the Throne of Glory. Therefore they said, “The soul You placed within me is pure,” for no corruption applies there, since it is a portion of the Divine. Love of the blessed God does not move away at all. Therefore they said, “If only they had abandoned Me but [kept] My Torah,” for the children of Israel cannot abandon Him, as it were, as in “With poured-out wrath I shall reign over you.” Even if a person greatly increases transgressions to provoke, the root of love of the blessed God, corresponding to Keter, the hidden root of thought, is not severed there at all, for “although he sinned, he is still Israel.” The First Temple’s destruction was for “their abandoning My Torah”; but through love of Torah, its light brings the hidden love of the blessed God into revelation.',
    'The fuller discussion connects the Flood generation’s intensity with desire for Torah, while distinguishing love of wisdom alone from Torah’s disclosure of love of God. The enduring hidden root and the need to bring it into expression are both retained.',book='tzidkat-hatzadik',anchorEnd='וְחַשְׁקוּת לְדִבְרֵי תוֹרָה,')
add(95,'peri-the-bright-rainbow-and-repentance',8,'Peri Tzadik, Matot 8:1',sub(local('peri-tzadik','Peri Tzadik, Matot 8:1'),'והקשת הוא בחינת מבטח עוז'),
    'The rainbow is the aspect of a strong assurance, for the Holy One, blessed be He, made a covenant that all flesh would never again be cut off by the waters of the Flood. [From the author’s manuscript.] Certainly this is not without a reason, if judgment calls for annihilation, for the Holy One, blessed be He, does not waive judgment. Rather, the rainbow, which is the appearance of the likeness of Hashem’s glory, awakens repentance. Therefore Tikkunei Zohar says: “When you see the rainbow in bright colors, look for the footsteps of the Messiah,” for Israel are redeemed only through repentance. “In bright colors” means that the awakening from above toward repentance will shine within the heart. Thus far. This means that even after all the corruptions in the world, repentance will avail, for “the inclination of the human heart is evil from youth.” This corresponds to Binah, the heart, as it is said, “His heart will understand, and he will return, and be healed.”',
    'The parallel explains the bright rainbow through an awakening to repentance in the heart. It explicitly preserves the condition of repentance and distinguishes the covenant’s promise from a simple waiver of judgment.',book='peri-tzadik')
add(95,'zohar-the-righteous-as-keepers-of-the-covenant',9,'Zohar, Noach 1:2-3',span('Zohar, Noach 1:2-3',1,2),
    'Come and see: all Israel have a share in the World to Come. Why? Because they guard the covenant upon which the world endures, as it is said, “Were it not for My covenant day and night, I would not have established the laws of heaven and earth.” Therefore Israel, who guard the covenant and accepted it, have a share in the World to Come. Moreover, for this reason they are called righteous. From here we learn that everyone who guards this covenant, upon which the world endures, is called righteous. From where do we know this? From Yosef: because he guarded the covenant of the world, he merited being called righteous. Therefore: “Your people are all righteous; they shall inherit the land forever.”',
    'This is the Zohar’s explicit explanation of “righteous” as guarding the covenant. It supplies the meaning invoked by the ois’s closing words.',cacheRef='Zohar, Noach 1:2-3',indices=[1,2])

E.sort(key=lambda e:(e['section'],e['rowN'],e['phraseIndex'],e['heCharOffset']))
reasons={
 91:'Added the author’s possessions/root principle, the creation-for-Israel Midrash, the accountability of instruments of harm, the deed’s own consequence, returning creation to its source, the interpretation of Yaakov’s flocks, the Talmud’s house-of-Yaakov explanation, and the personal/collective qualification concerning Yaakov and Sinai. Existing biblical, rabbinic, Tanya, and Tiferet Yosef quotations are preserved; their already-quoted passages are not repeated.',
 92:'Added the higher-repentance qualification, the distinct short-extension interpretation, the precise Yoma 42a scapegoat mnemonic, the gift-from-above with a required human response, and the Zohar’s ordinary sequence of awakening. Existing Flood interpretations, atonement parallels, and the Sod Yesharim gift/permanence connection are preserved.',
 93:'Added the plea in Eikhah Rabbah, Rabbeinu Bahya’s qualified account of the Second Temple, both actual Heikhalot passages, the earlier idolatrous-inclination episode, the verses on divine formation and help, Ramchal’s qualified account of Torah’s restoring light, the original Eikhah teaching, and the complete wisdom/prophecy distinctions in Resisei Layla and Ramban. Existing Gemara and connected passages remain unchanged. No speculative identification is added for the author’s previous sin.',
 94:'Added the awareness-of-presence teaching, the paired faces of wrath/favor, the Midrash’s removal of wrath, the always-open repentance gates with the surrounding prayer dispute, Rabbi Dosa’s death-vision teaching, and the Gemara’s interpretation of the passing face of wrath. Existing verses and the Resisei Layla connection remain unchanged.',
 95:'Added the root/future-repair distinction, the refinement of the good inclination, the fuller relation of Torah desire and love of God, the bright rainbow’s repentance condition, and the Zohar’s covenant/righteousness explanation. Existing Zohar and Tikkunei Zohar quotations, the Kometz rainbow note, and the Divrei Chalomot and Mei HaNoach connections are preserved; their already-quoted three-generation and rainbow passages are not repeated.'
}
